<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\ActivityLog;use App\Models\Company;use App\Models\Job;use App\Models\JobApplication;use App\Models\PaymentOrder;use App\Models\User;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReportController extends Controller{public function admin(Request $request):JsonResponse{abort_unless($request->user()->is_admin,403);$applications=JobApplication::select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status');return response()->json(['data'=>['summary'=>['users'=>User::count(),'candidates'=>User::where('account_type','candidate')->count(),'companies'=>Company::count(),'verified_companies'=>Company::where('verification_status','verified')->count(),'active_jobs'=>Job::where('status','active')->count(),'applications'=>JobApplication::count(),'approved_revenue'=>(float)PaymentOrder::where('status','approved')->sum('amount')],'applications_by_status'=>$applications,'recent_activity'=>ActivityLog::with('user:id,name,email')->latest()->limit(30)->get()]]);}public function company(Request $request):JsonResponse{abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);$jobs=$company->jobs();$applications=JobApplication::whereHas('job',fn($q)=>$q->where('company_id',$company->id));return response()->json(['data'=>['summary'=>['jobs'=>$jobs->count(),'active_jobs'=>(clone $jobs)->where('status','active')->count(),'applications'=>$applications->count(),'interviews'=>(clone $applications)->where('status','interview')->count(),'hired'=>(clone $applications)->where('status','hired')->count()],'applications_by_status'=>$applications->select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status'),'jobs'=>$company->jobs()->withCount('applications')->latest()->get(['id','title','status','published_at'])]]);}}
